\copy (SELECT json_build_object('id', q.id, 'subject', q.subject_area, 'exam', q.exam_type, 'q', q.question_text, 'a', q.option_a, 'b', q.option_b, 'c', q.option_c, 'd', q.option_d, 'e', q.option_e, 'key', q.correct_answer) FROM question_bank q WHERE q.is_active = true AND q.quality_review_status = 'unverified' AND q.correct_answer IN ('A','B','C','D','E') AND q.option_a IS NOT NULL AND q.option_b IS NOT NULL AND q.option_c IS NOT NULL AND q.option_d IS NOT NULL AND q.option_e IS NOT NULL AND q.word_count >= 8 AND q.pipeline_metadata->>'verified_provisional' IS DISTINCT FROM 'true' AND NOT EXISTS (SELECT 1 FROM question_bank_pool_growth_wave1_backup_20260603 b WHERE b.id = q.id) ORDER BY md5(q.id) LIMIT 3000) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_pool_growth_wave2/master.csv' CSV
